public class PrimitiveTypes {
    public static void main(String[] args) {
        // Integer types
        byte tiny = 127;           // 8-bit: -128 to 127
        short small = 32767;       // 16-bit: -32,768 to 32,767
        int regular = 2147483647;  // 32-bit (default for integers)
        long big = 9000000000L;    // 64-bit, suffix L required

        // Floating-point types
        float precise = 3.14f;     // 32-bit, suffix f required
        double accurate = 3.14159; // 64-bit (default for decimals)

        // Other primitives
        char letter = 'A';         // 16-bit Unicode character
        boolean flag = true;       // true or false only

        System.out.println("int: " + regular);
        System.out.println("double: " + accurate);
        System.out.println("char: " + letter);
        System.out.println("boolean: " + flag);
    }
}

public class Variables {
    public static void main(String[] args) {
        // Declaration then initialization
        int age;
        age = 25;

        // Declaration and initialization together
        double salary = 50000.50;

        // Multiple variables of same type
        int x = 1, y = 2, z = 3;

        // Final = constant (cannot be reassigned)
        final double PI = 3.14159;
        // PI = 3.14; // ERROR! Cannot assign to final variable

        // Underscores in numeric literals (for readability)
        long creditCard = 1234_5678_9012_3456L;
        int million = 1_000_000;

        System.out.println("Age: " + age);
        System.out.println("PI: " + PI);
        System.out.println("Million: " + million);
    }
}

public class TypeCasting {
    public static void main(String[] args) {
        // Implicit casting (widening): small → large
        int i = 100;
        long l = i;      // OK, no data loss
        double d = l;    // OK

        // Explicit casting (narrowing): large → small
        double pi = 3.99;
        int truncated = (int) pi;  // Loses decimal part: 3

        long big = 1000L;
        int small = (int) big;     // OK if value fits

        // Casting between char and int
        char letter = 'A';
        int ascii = letter;        // 65
        char back = (char) 66;     // 'B'

        System.out.println("Truncated: " + truncated);
        System.out.println("ASCII of A: " + ascii);
        System.out.println("Char 66: " + back);
    }
}

public class Arithmetic {
    public static void main(String[] args) {
        int a = 17, b = 5;

        System.out.println("a + b = " + (a + b));   // 22
        System.out.println("a - b = " + (a - b));   // 12
        System.out.println("a * b = " + (a * b));   // 85
        System.out.println("a / b = " + (a / b));   // 3 (integer division!)
        System.out.println("a % b = " + (a % b));   // 2 (remainder)

        // Integer division truncates
        System.out.println("17 / 5.0 = " + (17 / 5.0)); // 3.4

        // Increment and decrement
        int x = 5;
        System.out.println("x++ = " + (x++)); // 5 (post-increment)
        System.out.println("x = " + x);       // 6

        int y = 5;
        System.out.println("++y = " + (++y)); // 6 (pre-increment)
    }
}

public class RelationalLogical {
    public static void main(String[] args) {
        int a = 10, b = 20;

        // Relational operators
        System.out.println("a == b: " + (a == b)); // false
        System.out.println("a != b: " + (a != b)); // true
        System.out.println("a > b: " + (a > b));   // false
        System.out.println("a < b: " + (a < b));   // true

        // Logical operators
        boolean x = true, y = false;
        System.out.println("x && y: " + (x && y)); // false (AND)
        System.out.println("x || y: " + (x || y)); // true (OR)
        System.out.println("!x: " + (!x));         // false (NOT)

        // Short-circuit evaluation
        int num = 5;
        if (num != 0 && 10 / num > 1) {
            System.out.println("Safe division");
        }
    }
}

public class Assignment {
    public static void main(String[] args) {
        int a = 10;

        // Compound assignment operators
        a += 5;   // a = a + 5 → 15
        a -= 3;   // a = a - 3 → 12
        a *= 2;   // a = a * 2 → 24
        a /= 4;   // a = a / 4 → 6
        a %= 4;   // a = a % 4 → 2

        System.out.println("Final a: " + a);

        // Ternary operator
        int score = 75;
        String grade = (score >= 60) ? "Pass" : "Fail";
        System.out.println("Grade: " + grade);

        // Chained ternary
        String level = (score >= 90) ? "A" : (score >= 80) ? "B" : "C";
        System.out.println("Level: " + level);
    }
}

public class IfElse {
    public static void main(String[] args) {
        int score = 85;

        if (score >= 90) {
            System.out.println("Grade: A");
        } else if (score >= 80) {
            System.out.println("Grade: B");
        } else if (score >= 70) {
            System.out.println("Grade: C");
        } else if (score >= 60) {
            System.out.println("Grade: D");
        } else {
            System.out.println("Grade: F");
        }

        // Single-line if (no braces for single statement)
        if (score > 0)
            System.out.println("Valid score");
    }
}

public class SwitchDemo {
    public static void main(String[] args) {
        int day = 3;
        String dayName;

        // Traditional switch
        switch (day) {
            case 1:
                dayName = "Monday";
                break;
            case 2:
                dayName = "Tuesday";
                break;
            case 3:
                dayName = "Wednesday";
                break;
            case 4:
                dayName = "Thursday";
                break;
            case 5:
                dayName = "Friday";
                break;
            default:
                dayName = "Weekend";
        }
        System.out.println("Day: " + dayName);

        // Enhanced switch (Java 14+)
        String result = switch (day) {
            case 1, 2, 3, 4, 5 -> "Weekday";
            case 6, 7 -> "Weekend";
            default -> "Invalid";
        };
        System.out.println("Type: " + result);
    }
}

public class Loops {
    public static void main(String[] args) {
        // for loop
        System.out.println("for loop:");
        for (int i = 0; i < 5; i++) {
            System.out.print(i + " ");
        }
        System.out.println();

        // while loop
        System.out.println("while loop:");
        int j = 0;
        while (j < 5) {
            System.out.print(j + " ");
            j++;
        }
        System.out.println();

        // do-while loop (executes at least once)
        System.out.println("do-while loop:");
        int k = 0;
        do {
            System.out.print(k + " ");
            k++;
        } while (k < 5);
        System.out.println();

        // Enhanced for loop (for-each)
        System.out.println("for-each loop:");
        int[] numbers = {10, 20, 30, 40, 50};
        for (int num : numbers) {
            System.out.print(num + " ");
        }
        System.out.println();

        // break and continue
        System.out.println("break at 3:");
        for (int i = 0; i < 10; i++) {
            if (i == 3) break;
            System.out.print(i + " ");
        }
    }
}

