public class GenericMethods {
    // Generic method
    public static <T> void printArray(T[] array) {
        for (T element : array) {
            System.out.println(element);
        }
    }

    // Bounded type parameter
    public static <T extends Comparable<T>> T findMax(T[] array) {
        T max = array[0];
        for (T element : array) {
            if (element.compareTo(max) > 0) {
                max = element;
            }
        }
        return max;
    }

    // Multiple bounds
    public static <T extends Number & Comparable<T>> T findMaxNumber(List<T> list) {
        T max = list.get(0);
        for (T num : list) {
            if (num.compareTo(max) > 0) {
                max = num;
            }
        }
        return max;
    }

    public static void main(String[] args) {
        Integer[] numbers = {3, 1, 4, 1, 5, 9};
        System.out.println("Max: " + findMax(numbers));

        String[] words = {"cherry", "apple", "banana"};
        System.out.println("Max: " + findMax(words));

        List<Double> doubles = Arrays.asList(3.14, 2.71, 1.41);
        System.out.println("Max double: " + findMaxNumber(doubles));
    }
}

