// Define custom annotation
@Retention(RetentionPolicy.RUNTIME)  // Available at runtime
@Target(ElementType.METHOD)          // Can only be applied to methods
public @interface Test {
    String value() default "";
    int priority() default 0;
}

// Usage
public class TestRunner {
    @Test(priority = 1)
    public void testOne() {
        System.out.println("Running test one");
    }

    @Test  // Uses default values
    public void testTwo() {
        System.out.println("Running test two");
    }

    // Process annotations via reflection
    public static void main(String[] args) throws Exception {
        for (java.lang.reflect.Method m : TestRunner.class.getDeclaredMethods()) {
            if (m.isAnnotationPresent(Test.class)) {
                Test annotation = m.getAnnotation(Test.class);
                System.out.println("Method: " + m.getName() + ", Priority: " + annotation.priority());
                m.invoke(new TestRunner());
            }
        }
    }
}

