        Counter counter = new Counter();
        Thread[] threads = new Thread[1000];
        for (int i = 0; i < 1000; i++) {
            threads[i] = new Thread(counter::increment);
            threads[i].start();
        }
        for (Thread t : threads) t.join();
        System.out.println("Expected: 1000, Actual: " + counter.getCount());

        java.util.concurrent.atomic.AtomicInteger atomicCount = 
            new java.util.concurrent.atomic.AtomicInteger(0);
        for (int i = 0; i < 1000; i++) {
            new Thread(atomicCount::incrementAndGet).start();
        }
        Thread.sleep(1000);
        System.out.println("Atomic count: " + atomicCount.get());
    }
}

