public class HeapDemo {
    public static void main(String[] args) {
        // Get runtime info
        Runtime runtime = Runtime.getRuntime();

        long maxMemory = runtime.maxMemory();
        long totalMemory = runtime.totalMemory();
        long freeMemory = runtime.freeMemory();
        long usedMemory = totalMemory - freeMemory;

        System.out.println("Max heap: " + bytesToMB(maxMemory) + " MB");
        System.out.println("Total heap: " + bytesToMB(totalMemory) + " MB");
        System.out.println("Free heap: " + bytesToMB(freeMemory) + " MB");
        System.out.println("Used heap: " + bytesToMB(usedMemory) + " MB");

        // Allocate objects to see heap grow
        for (int i = 0; i < 1_000_000; i++) {
            new Object();  // These become eligible for GC immediately
        }

        System.gc();  // Suggest GC (not guaranteed)

        System.out.println("\nAfter allocation + GC suggestion:");
        System.out.println("Used heap: " + bytesToMB(runtime.totalMemory() - runtime.freeMemory()) + " MB");
    }

    static long bytesToMB(long bytes) {
        return bytes / (1024 * 1024);
    }
}

public class GarbageCollection {
    public static void main(String[] args) {
        // Object 1: referenced, NOT eligible for GC
        Person p1 = new Person("Alice");

        // Object 2: loses reference, becomes eligible for GC
        Person p2 = new Person("Bob");
        p2 = null;

        // Object 3: reference reassigned, old object eligible for GC
        Person p3 = new Person("Charlie");
        p3 = new Person("Dave");  // "Charlie" object is now unreachable

        // Object 4: inside method, eligible after method returns
        createTemporary();

        // Request GC (for demonstration only — never do this in production)
        System.gc();

        System.out.println("Still alive: " + p1.name);
        System.out.println("Still alive: " + p3.name);
    }

    static void createTemporary() {
        Person temp = new Person("Temporary");
        // temp is eligible for GC after this method returns
    }
}

