public class ParameterizedTestDemo {

    // Run same test with multiple values
    @ParameterizedTest
    @ValueSource(strings = {"racecar", "radar", "level", "madam"})
    void isPalindrome(String candidate) {
        assertTrue(isPalindrome(candidate), candidate + " should be palindrome");
    }

    // CSV source for multiple parameters
    @ParameterizedTest
    @CsvSource({
        "1, 1, 2",      // a, b, expected
        "2, 3, 5",
        "10, 20, 30",
        "-5, 5, 0"
    })
    void add(int a, int b, int expected) {
        Calculator calc = new Calculator();
        assertEquals(expected, calc.add(a, b));
    }

    // Method source for complex data
    @ParameterizedTest
    @MethodSource("provideStringsForIsBlank")
    void isBlank(String input, boolean expected) {
        assertEquals(expected, input == null || input.trim().isEmpty());
    }

    static Stream<Arguments> provideStringsForIsBlank() {
        return Stream.of(
            Arguments.of(null, true),
            Arguments.of("", true),
            Arguments.of("  ", true),
            Arguments.of("not blank", false)
        );
    }

    boolean isPalindrome(String s) {
        return s.equals(new StringBuilder(s).reverse().toString());
    }
}

